FILE: macroCallForms.cj
    package macrocalls
    import std.ast.*
    <element: CfirMacroDeclaration>
    <element: CfirMacroDeclaration>
    internal? func macroCalls(): R|Int64| {
        local? let a: <implicit> = ...
